function M.layout(info)
  local mf = main_file(info.kind)
  return table.concat({
    info.name .. "/",
    "  Cargo.toml        [workspace] resolver " .. info.resolver .. ', members = ["crates/*"], edition ' .. info.edition,
    "  .gitignore        /target",
    "  crates/" .. info.member .. "/",
    "    Cargo.toml      version and edition inherited",
    "    " .. mf,
  }, "\n")
end'''),
